import math, random, sys
import synth_api as S

SEED = 10193
rng = random.Random(SEED)
S.new_scene(ground="warm", world="sky", sun_energy=3.0, sun_elev_deg=45, sun_az_deg=rng.choice([10, 40]))

# a scattering of primitives at several depths so the camera's translation is clearly visible (parallax)
spec = [("cube", "red", (-4.0, 0.5)), ("cone", "blue", (-1.5, -1.0)), ("cylinder", "green", (1.5, 1.5)),
        ("ball", "yellow", (3.5, -0.5)), ("cube", "purple", (-2.5, 3.5)), ("cone", "orange", (0.5, 4.5)),
        ("cylinder", "red", (4.5, 3.0))]
for i, (shape, colour, (x, y)) in enumerate(spec):
    o = S.spawn_primitive(shape, colour, rng.choice([0.3, 0.4, 0.5]), f"{colour}_{shape}_{i}")
    S.place(o, x + rng.uniform(-0.2, 0.2), y + rng.uniform(-0.2, 0.2))

# camera keeps one heading (looking along +y) and only translates: left, then forward, then right
cam = S.add_camera((0, -9.0, 1.5), (0, 10, 1.5))
cam.rotation_euler = (math.radians(90), 0, 0)


def pos(f):
    if f <= 8:
        return (-3.5 * (f - 1) / 7, -9.0)
    if f <= 16:
        return (-3.5, -9.0 + 3.5 * (f - 8) / 8)
    return (-3.5 + 6.0 * (f - 16) / 8, -5.5)


for f in range(1, 25):
    x, y = pos(f)
    cam.location = (x, y, 1.5)
    cam.keyframe_insert("location", frame=f)
for fc in cam.animation_data.action.fcurves:
    for kp in fc.keyframe_points:
        kp.interpolation = "LINEAR"
S.save(sys.argv[sys.argv.index("--") + 1])

