import sys
import synth_facts as F

F.load(sys.argv[1])
tags = F.objects()
desc = {}
for n, t in tags.items():
    desc.setdefault(t["descriptor"], []).append(n)
names = {"red cube": "red cubes", "blue ball": "blue balls", "yellow cone": "yellow cones",
         "purple cylinder": "purple cylinders"}
cnt = {d: len(v) for d, v in desc.items()}
rep = {d: desc[d][0] for d in desc}
facts = []

def cmp(a, b):
    return "more " + names[a] if cnt[a] > cnt[b] else ("more " + names[b] if cnt[b] > cnt[a] else "equal")

top = max(cnt, key=cnt.get)
bot = min(cnt, key=cnt.get)
facts.append(F.fact("f1", f"There are most {names[top]}.", "other", names[top], objects=[x for v in desc.values() for x in v]))
facts.append(F.fact("f2", f"Fewest are {names[bot]}.", "other", names[bot], objects=[x for v in desc.values() for x in v]))
facts.append(F.fact("f3", "Red cubes vs blue balls.", "other", cmp("red cube", "blue ball"), objects=desc["red cube"] + desc["blue ball"]))
facts.append(F.fact("f4", "Yellow cones vs purple cylinders.", "other", cmp("yellow cone", "purple cylinder"), objects=desc["yellow cone"] + desc["purple cylinder"]))
facts.append(F.fact("f5", "Blue balls vs yellow cones.", "other", cmp("blue ball", "yellow cone"), objects=desc["blue ball"] + desc["yellow cone"]))
facts.append(F.fact("f6", "How many more red cubes than blue balls.", "other", cnt["red cube"] - cnt["blue ball"], objects=desc["red cube"] + desc["blue ball"]))
F.write(facts, sys.argv[2])
